from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone("America/New_York")

        equity = self.add_equity("SPY", Resolution.MINUTE)
        equity.set_data_normalization_mode(DataNormalizationMode.RAW)
        self.spy = equity.symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(
            lambda universe:
                universe.include_weeklys()
                .strikes(-100, 100)
                .expiration(0, 730)
        )
        self.option_symbol = option.symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_closes = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.blocked_entry_date = None
        self.equity_liquidation_ticket = None

        self.schedule.on(
            self.date_rules.every_day(self.spy),
            self.time_rules.at(9, 30),
            self._expiration_guard
        )

    def on_data(self, slice: Slice):
        now = self.time
        current_date = now.date()

        # Assignment/exercise must never leave an SPY equity position open.
        spy_quantity = self.portfolio[self.spy].quantity
        if spy_quantity != 0:
            if self.equity_liquidation_ticket is None:
                self.debug(
                    f"{now}: Unexpected SPY equity position detected; "
                    f"liquidating {spy_quantity} shares"
                )
                self.equity_liquidation_ticket = self.market_order(
                    self.spy, -spy_quantity
                )

        # Expiration-day protection in case the scheduled event was missed.
        if (
            self.held_symbol is not None
            and self.held_symbol.id.date.date() <= current_date
        ):
            self.blocked_entry_date = current_date
            self._liquidate_option("expiration protection")

        # Evaluate option exits on every minute Slice.
        self._evaluate_option_exits(slice)

        # Build five-minute bars only from complete, contiguous minute bars.
        spy_bar = slice.bars.get(self.spy)
        if spy_bar is None:
            return

        minute_start = spy_bar.time.replace(second=0, microsecond=0)
        bucket_start = minute_start - timedelta(
            minutes=minute_start.minute % 5
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._finish_five_minute_bar(slice)
            self.bucket_start = bucket_start
            self.bucket_closes = {}

        self.bucket_closes[minute_start] = float(spy_bar.close)

    def _finish_five_minute_bar(self, slice: Slice):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # Do not synthesize a bar from incomplete or non-contiguous data.
        if any(t not in self.bucket_closes for t in expected_times):
            return

        close = self.bucket_closes[expected_times[-1]]
        bar_end = self.bucket_start + timedelta(minutes=5)

        if len(self.slow_closes) >= 20:
            self.previous_fast = sum(self.fast_closes) / 5.0
            self.previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        end_time = bar_end.time()
        if not (
            time(9, 45) <= end_time <= time(14, 30)
        ):
            return

        if self.blocked_entry_date == self.time.date():
            return

        self._try_enter_call(slice, close)

    def _try_enter_call(self, slice: Slice, spy_price: float):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._order_is_open(
            self.entry_ticket
        ):
            return

        chain = slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug(f"{self.time}: Entry skipped: no option chain")
            return

        minimum_expiration = self.time.date() + timedelta(days=7)

        contracts = list(chain.contracts.values())

        expirations = sorted({
            contract.id.date.date()
            for contract in contracts
            if contract.id.option_right == OptionRight.CALL
            and contract.id.date.date() >= minimum_expiration
        })

        if not expirations:
            self.debug(
                f"{self.time}: Entry skipped: no expiration at least "
                f"7 calendar days away"
            )
            return

        expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.id.option_right == OptionRight.CALL
            and contract.id.date.date() == expiration
            and contract.id.strike_price >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"{self.time}: Entry skipped: no qualifying call for "
                f"{expiration}"
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                contract.id.strike_price,
                str(contract.symbol)
            )
        )[0]

        self.entry_ticket = self.market_order(selected.symbol, 1)
        self.debug(
            f"{self.time}: Entry submitted: {selected.symbol}"
        )

    def _evaluate_option_exits(self, slice: Slice):
        if self.held_symbol is None:
            return

        expiration_date = self.held_symbol.id.date.date()
        current_date = self.time.date()

        # Time stop at 15:45 on the trading day immediately before expiration.
        if (
            self._is_immediately_preceding_trading_day(
                current_date, expiration_date
            )
            and self.time.hour == 15
            and self.time.minute == 45
        ):
            self._liquidate_option("pre-expiration time stop")
            return

        chain = slice.option_chains.get(self.option_symbol)
        if chain is None:
            return

        contract = chain.contracts.get(self.held_symbol)
        if contract is None:
            return

        bid = float(contract.bid_price)
        ask = float(contract.ask_price)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        ):
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._order_is_open(
            self.exit_ticket
        ):
            return

        quantity = self.portfolio[self.held_symbol].quantity
        if quantity == 0:
            return

        # There is only one strategy-created exit ticket, so cancel it before
        # submitting the replacement liquidation order.
        if self.exit_ticket is not None:
            self.transactions.cancel_order(self.exit_ticket.order_id)

        self.exit_ticket = self.market_order(
            self.held_symbol, -quantity
        )
        self.debug(
            f"{self.time}: Exit submitted ({reason}): "
            f"{self.held_symbol}"
        )

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status == OrderStatus.FILLED:
            if (
                self.entry_ticket is not None
                and order_event.order_id == self.entry_ticket.order_id
            ):
                self.held_symbol = self.entry_ticket.symbol
                self.entry_price = float(order_event.fill_price)
                self.debug(
                    f"{self.time}: Entry filled: {self.held_symbol}, "
                    f"price={self.entry_price}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.order_id == self.exit_ticket.order_id
            ):
                self.debug(
                    f"{self.time}: Exit filled: {self.exit_ticket.symbol}"
                )
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

        if (
            self.entry_ticket is not None
            and order_event.order_id == self.entry_ticket.order_id
            and order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            )
        ):
            self.debug(
                f"{self.time}: Entry order failed: "
                f"{order_event.status}"
            )
            self.entry_ticket = None

    def on_assignment_order_event(self, assignment_event: OrderEvent):
        self.debug(
            f"{self.time}: Unexpected exercise or assignment: "
            f"{assignment_event}"
        )

        self.blocked_entry_date = self.time.date()

        quantity = self.portfolio[self.spy].quantity
        if quantity != 0:
            self.equity_liquidation_ticket = self.market_order(
                self.spy, -quantity
            )

    def _expiration_guard(self):
        current_date = self.time.date()
        self.blocked_entry_date = current_date

        if self.held_symbol is not None:
            expiration_date = self.held_symbol.id.date.date()
            if expiration_date <= current_date:
                self._liquidate_option("expiration processing")

    def _is_immediately_preceding_trading_day(
        self,
        current_date,
        expiration_date
    ):
        candidate = expiration_date - timedelta(days=1)

        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)

        try:
            is_open = self.securities[self.spy].exchange.hours.is_date_open(
                datetime.combine(candidate, time(0, 0))
            )
            if not is_open:
                candidate -= timedelta(days=1)
                while candidate.weekday() >= 5:
                    candidate -= timedelta(days=1)
        except Exception:
            # Weekday fallback only protects compatibility with LEAN builds
            # exposing different exchange-hours Python bindings.
            pass

        return current_date == candidate

    @staticmethod
    def _order_is_open(ticket):
        return ticket is not None and ticket.status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID,
            OrderStatus.REJECTED
        )
