from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time
from statistics import mean


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.options = self.AddOption(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        self.options.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=21)

        self._bucket_date = None
        self._bucket_start = None
        self._bucket_minutes = {}

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_option = None
        self._entry_price = None
        self._time_stop_date = None
        self._expiration_day_blocked = None

    def OnData(self, slice: Slice):
        # Immediately remove any SPY equity position caused by exercise or assignment.
        spy_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected: {spy_quantity}; liquidating."
            )
            self.MarketOrder(
                self.spy.Symbol,
                -spy_quantity,
                tag="Unexpected exercise/assignment liquidation"
            )

        completed_bar = None

        if slice.Bars.ContainsKey(self.spy.Symbol):
            minute_bar = slice.Bars[self.spy.Symbol]
            completed_bar = self._update_five_minute_bar(minute_bar)

        self._manage_open_option(slice)

        if completed_bar is not None:
            self._evaluate_signal(completed_bar, slice)

    def _update_five_minute_bar(self, minute_bar):
        bar_time = minute_bar.Time
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return None

        bar_date = bar_time.date()
        session_start = datetime.combine(bar_date, time(9, 30))
        minutes_since_open = int((bar_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_since_open // 5) * 5
        )

        completed = None

        if (
            self._bucket_start is not None
            and bucket_start != self._bucket_start
        ):
            completed = self._finalize_bucket()

        if self._bucket_date != bar_date:
            self._bucket_date = bar_date
            self._bucket_start = None
            self._bucket_minutes = {}

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._bucket_minutes = {}

        self._bucket_minutes[bar_time.replace(second=0, microsecond=0)] = minute_bar

        return completed

    def _finalize_bucket(self):
        if self._bucket_start is None:
            return None

        expected_times = [
            self._bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # Missing minute data means the five-minute bar is not valid.
        if any(t not in self._bucket_minutes for t in expected_times):
            return None

        bars = [self._bucket_minutes[t] for t in expected_times]

        consolidated = TradeBar(
            self._bucket_start,
            self._bucket_start + timedelta(minutes=5),
            self.spy.Symbol,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars)
        )

        self.closes.append(float(consolidated.Close))
        return consolidated

