            spy_bar = slice.Bars[self.spy_symbol]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime.replace(second=0, microsecond=0)

        if end_time.time() <= time(9, 30) or end_time.time() > time(16, 0):
            return

        window_end = end_time + timedelta(
            minutes=(5 - end_time.minute % 5) % 5
        )

        if window_end.minute % 5 != 0:
            window_end += timedelta(
                minutes=5 - window_end.minute % 5
            )

        if window_end.time() < time(9, 35):
            window_end = window_end.replace(
                hour=9, minute=35
            )

        window = self.minute_windows.setdefault(window_end, {})
        window[end_time] = bar

        completed_windows = [
            key for key in self.minute_windows
            if key <= window_end
        ]

        for completed_end in sorted(completed_windows):
            bars = self.minute_windows.pop(completed_end)

            expected_times = [
                completed_end - timedelta(minutes=minutes_ago)
                for minutes_ago in range(1, 6)
            ]

            if any(expected not in bars for expected in expected_times):
                continue

            ordered_bars = [
                bars[expected]
