            self.Debug("Skipped call selection: no qualifying call.")
            return

        candidates.sort(
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

