                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                if order_event.Status != OrderStatus.Filled:
                    self.Debug("Entry order did not fully fill.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol.Value}; "
                        f"price {order_event.FillPrice:.4f}"
                    )
                    self._clear_position_state()

                self.exit_ticket = None

        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        is_exercise = bool(getattr(order_event, "IsExercise", False))

        if is_assignment or is_exercise:
            self.Debug(
                f"Unexpected exercise/assignment event: "
                f"{order_event.Symbol.Value}"
            )
            self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected: {quantity}; "
                f"liquidating immediately."
            )
            self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.no_entry_today = True

    def _clear_position_state(self):
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
