from collections import deque
from datetime import datetime, date, time, timedelta

from AlgorithmImports import *


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.previous_fast = None
        self.previous_slow = None

        self.minute_windows = {}
        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None

        self.current_date = None
        self.no_entry_today = False
        self.time_stop_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.current_date != today:
            self.current_date = today
            self.no_entry_today = False
            self.time_stop_date = None

        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if today >= expiry:
                self.no_entry_today = True
                self._submit_exit("expiration protection")
            else:
                self._check_time_stop(today, expiry)
                self._check_profit_target(slice)

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy_symbol):
            spy_bar = slice.Bars[self.spy_symbol]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime.replace(second=0, microsecond=0)

        if end_time.time() <= time(9, 30) or end_time.time() > time(16, 0):
            return

        window_end = end_time + timedelta(
            minutes=(5 - end_time.minute % 5) % 5
        )

        if window_end.minute % 5 != 0:
            window_end += timedelta(
                minutes=5 - window_end.minute % 5
            )

        if window_end.time() < time(9, 35):
            window_end = window_end.replace(
                hour=9, minute=35
            )

        window = self.minute_windows.setdefault(window_end, {})
        window[end_time] = bar

        completed_windows = [
            key for key in self.minute_windows
            if key <= window_end
        ]

        for completed_end in sorted(completed_windows):
            bars = self.minute_windows.pop(completed_end)

            expected_times = [
                completed_end - timedelta(minutes=minutes_ago)
                for minutes_ago in range(1, 6)
            ]

            if any(expected not in bars for expected in expected_times):
                continue

            ordered_bars = [
                bars[expected]
                for expected in reversed(expected_times)
            ]

            consolidated = self._consolidate_bars(ordered_bars)
            self._process_five_minute_bar(consolidated, slice)

    def _consolidate_bars(self, bars):
        return TradeBar(
            bars[0].Time,
            self.spy_symbol,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            bars[-1].EndTime - bars[0].Time
        )

    def _process_five_minute_bar(self, bar: TradeBar, slice: Slice):
        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)

        if (
            bullish_crossover
            and eligible_time
            and not self.no_entry_today
            and self.held_symbol is None
            and self.entry_ticket is None
        ):
            self._try_enter(slice, float(bar.Close))

    def _try_enter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        candidates.sort(
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}"
        )

    def _check_profit_target(self, slice: Slice):
        if (
            self.held_symbol is None
            or self.entry_price is None
            or self.exit_ticket is not None
        ):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = next(
            (
                contract for contract in chain
                if contract.Symbol == self.held_symbol
            ),
            None
        )

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._cancel_open_exit_order()
            self._submit_exit("50% profit target")

    def _check_time_stop(self, today: date, expiry: date):
        if self.Time.time() < time(15, 45):
            return

        if self.time_stop_date == today:
            return

        if self._is_immediately_before_expiry(today, expiry):
            self.time_stop_date = today
            self._submit_exit("expiration-eve time stop")

    def _is_immediately_before_expiry(self, current_date: date, expiry: date):
        candidate = current_date + timedelta(days=1)

        while candidate < expiry:
            if self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
                candidate
            ):
                return False
            candidate += timedelta(days=1)

        return candidate == expiry

    def _submit_exit(self, reason: str):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            self._clear_position_state()
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            f"Exit submitted: {self.held_symbol.Value}; reason: {reason}"
        )

    def _cancel_open_exit_order(self):
        if self.exit_ticket is None:
            return

        if self.exit_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        ):
            self.exit_ticket.Cancel("Canceled for profit-target exit")

        self.exit_ticket = None

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)

                self.Debug(
                    f"Entry filled: {self.held_symbol.Value}; "
                    f"price {self.entry_price:.4f}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                if order_event.Status != OrderStatus.Filled:
                    self.Debug("Entry order did not fully fill.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol.Value}; "
                        f"price {order_event.FillPrice:.4f}"
                    )
                    self._clear_position_state()

                self.exit_ticket = None

        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        is_exercise = bool(getattr(order_event, "IsExercise", False))

        if is_assignment or is_exercise:
            self.Debug(
                f"Unexpected exercise/assignment event: "
                f"{order_event.Symbol.Value}"
            )
            self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected: {quantity}; "
                f"liquidating immediately."
            )
            self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.no_entry_today = True

    def _clear_position_state(self):
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None

