                ):
                    self._liquidate_option("expiration time stop")
                else:
                    self._check_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        consolidated_bar = self._add_minute_bar(spy_bar)
        if consolidated_bar is None:
            return

        self._update_averages_and_check_signal(consolidated_bar, slice)

    def _add_minute_bar(self, minute_bar: TradeBar):
        local_time = minute_bar.EndTime

        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        session_start = datetime(
            local_time.year,
            local_time.month,
            local_time.day,
            9,
            30
        )
        session_end = datetime(
            local_time.year,
            local_time.month,
            local_time.day,
            16,
            0
        )

        if local_time < session_start or local_time > session_end:
            return None

        minutes_from_open = int((local_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )
        minute_offset = int((local_time - bucket_start).total_seconds() // 60)

        if self.current_bucket_start != bucket_start:
            self.current_bucket_start = bucket_start
            self.bucket_bars = {}

        if minute_offset < 0 or minute_offset > 4:
            return None

        self.bucket_bars[minute_offset] = minute_bar

        # The bar ending at 09:35 contains minutes 09:30 through 09:34.
        if minute_offset != 4:
            return None

        if len(self.bucket_bars) != 5:
            self.bucket_bars = {}
            return None

        if set(self.bucket_bars.keys()) != {0, 1, 2, 3, 4}:
            self.bucket_bars = {}
            return None

        bars = [self.bucket_bars[i] for i in range(5)]

        consolidated = TradeBar(
            bucket_start,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars)
        )

        self.bucket_bars = {}
        return consolidated

    def _update_averages_and_check_signal(self, bar: TradeBar, slice: Slice):
        previous_fast = self.fast[-1] if len(self.fast) >= self.fast_period else None
        previous_slow = self.slow[-1] if len(self.slow) >= self.slow_period else None

        self.fast.append(bar.Close)
        self.slow.append(bar.Close)

        if len(self.fast) > self.fast_period:
            self.fast.pop(0)

        if len(self.slow) > self.slow_period:
            self.slow.pop(0)

        if len(self.fast) < self.fast_period or len(self.slow) < self.slow_period:
            return

        current_fast = sum(self.fast[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.slow[-self.slow_period:]) / self.slow_period

        if previous_fast is None or previous_slow is None:
            return

        bar_end_time = bar.EndTime
        if bar_end_time.tzinfo is not None:
            bar_end_time = bar_end_time.replace(tzinfo=None)

        if not (
            time(9, 45) <= bar_end_time.time() <= time(14, 30)
        ):
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_crossover:
            self._try_enter(slice, bar.Close, bar_end_time.date())

    def _try_enter(self, slice: Slice, spy_price: float, signal_date):
        if self.no_entry_date == signal_date:
            return

        if self.held_symbol is not None:
            return

        if self._entry_order_open():
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = slice.OptionChains.get(self.spy_option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = signal_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration."
            )
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))

        selected = candidates[0]

        self.entry_fill_quantity = 0
        self.entry_fill_value = 0.0
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiration={selected_expiry}; strike={selected.Strike}"
        )

    def _check_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._exit_order_open():
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_order_open():
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {self.held_symbol}; reason={reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_fill_quantity += order_event.FillQuantity
                    self.entry_fill_value += (
                        order_event.FillQuantity * order_event.FillPrice
                    )

                    if self.entry_fill_quantity > 0:
                        self.entry_price = (
                            self.entry_fill_value /
                            self.entry_fill_quantity
                        )
                        self.held_symbol = order_event.Symbol

                        self.Debug(
                            f"Entry filled: {self.held_symbol}; "
                            f"price={self.entry_price:.4f}"
                        )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None_
                ):
                    self.entry_ticket = None
                    self.entry_fill_quantity = 0
                    self.entry_fill_value = 0.0

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    if (
                        self.held_symbol is None
                        or self.Portfolio[self.held_symbol].Quantity == 0
                    ):
                        self.Debug(
                            f"Exit filled: {order_event.Symbol}; "
                            f"price={order_event.FillPrice:.4f}"
                        )
                        self.held_symbol = None
                        self.entry_price = None
                        self.entry_ticket = None
                        self.exit_ticket = None
                        self.entry_fill_quantity = 0
                        self.entry_fill_value = 0.0

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
