    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        self.Debug(
            f"Unexpected option exercise or assignment: "
            f"{assignment_event.Symbol}"
        )
        self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity

        if spy_quantity == 0:
            return

        if (
            self.spy_liquidation_ticket is not None
            and self._order_open(self.spy_liquidation_ticket)
        ):
            return

        self.Debug(
            f"Unexpected SPY equity position detected: "
            f"{spy_quantity}; liquidating immediately."
        )

        self.spy_liquidation_ticket = self.MarketOrder(
            self.spy,
            -spy_quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while True:
            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )

            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                candidate_datetime
            ):
                return candidate

            candidate -= timedelta(days=1)

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self._order_open(self.entry_ticket)
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self._order_open(self.exit_ticket)
        )

    @staticmethod
    def _order_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

