    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        local_date = bar_time.date()
        minute = bar_time.hour * 60 + bar_time.minute
        session_start = 9 * 60 + 30
        session_end = 16 * 60

        if minute < session_start or minute >= session_end:
            return

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )
        bucket_end = bucket_start + timedelta(minutes=5)

        self.minute_bars[bar_time] = bar

        # The fifth minute of the bucket is timestamped four minutes
        # after the bucket start when using minute TradeBars.
        if bar_time.minute % 5 != 4:
            return

        if bucket_start in self.completed_buckets:
            return

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        bucket_bars = [
            self.minute_bars.get(expected_time)
            for expected_time in expected_times
        ]

        self.completed_buckets.add(bucket_start)

        # Missing minute data means no consolidated bar is created.
        if any(item is None for item in bucket_bars):
            return

        consolidated_close = float(bucket_bars[-1].Close)
        self._process_completed_five_minute_bar(
            bucket_end,
            consolidated_close,
            slice
        )

