            self.closes.pop(0)

        self.closes.append(close)

        if len(self.closes) >= self.fast_period:
            self.fast_sum = sum(self.closes[-self.fast_period:])
            current_fast = self.fast_sum / self.fast_period
        else:
            current_fast = None

        if len(self.closes) >= self.slow_period:
            self.slow_sum = sum(self.closes[-self.slow_period:])
            current_slow = self.slow_sum / self.slow_period
        else:
            current_slow = None

        crossover = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            current_fast is not None and
            current_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        bar_time = bar_end_time.time()
        eligible_time = (
            bar_time >= time(9, 45) and
            bar_time <= time(14, 30)
        )

        if (
            crossover and
            eligible_time and
            self.no_entry_date != self.Time.date()
        ):
            self._try_enter(slice)

        if current_fast is not None and current_slow is not None:
            self.previous_fast = current_fast
            self.previous_slow = current_slow

    def _try_enter(self, slice: Slice):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(
            self.entry_ticket
        ):
            return

        if self.latest_spy_price is None or self.latest_spy_price <= 0:
            self.Debug("Skipped entry: SPY price unavailable.")
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        contracts = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date()
            for contract in contracts
        )

        strike_floor = self.latest_spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId
        self.entry_price = None

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None and
            order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                if order_event.FillPrice > 0:
                    self.entry_price = float(order_event.FillPrice)

                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.Debug(
                        "Entry filled: {0} at {1}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                    self.entry_ticket = None
                    self.entry_order_id = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None
                self.entry_order_id = None
                self.entry_price = None

        if (
            self.exit_order_id is not None and
            order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.exit_order_id = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None
                self.exit_order_id = None

        if order_event.OrderType == OrderType.OptionExercise:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment detected.")
            self._handle_unexpected_spy_position()

    def _evaluate_held_position(self, slice: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(
            self.exit_ticket
        ):
            return

        quote = slice.QuoteBars.get(self.held_symbol)

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _handle_expiration_processing(self, current_date):
        if self.held_symbol is None:
            return

        security = self.Securities.get(self.held_symbol)
        if security is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration processing")

            if self.entry_ticket is not None:
                self.entry_ticket.Cancel("Expiration processing")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = int(holding.Quantity)

        if quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(
            self.exit_ticket
        ):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug(
            "Exit submitted: {0}, quantity {1}".format(
                reason,
                quantity
            )
        )

    def _handle_unexpected_spy_position(self):
        quantity = int(self.Portfolio[self.spy].Quantity)

        if quantity != 0:
            self.no_entry_date = self.Time.date()
            self.Debug(
                "Unexpected SPY equity position detected; liquidating."
            )
            self.MarketOrder(self.spy, -quantity)

    def _handle_entry_order_state(self):
        if self.entry_ticket is None:
            return

        if not self._ticket_is_open(self.entry_ticket):
            status = self.entry_ticket.Status

            if status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                self.entry_ticket = None
                self.entry_order_id = None

    def _ticket_is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.PartiallyFilled,
            OrderStatus.Submitted,
            OrderStatus.CancelPending
        )

    def OnEndOfAlgorithm(self):
        if self.held_symbol is not None:
            self.Debug(
                "Warning: option position remains at end of algorithm."
            )

