    def on_assignment_order_event(self, assignment_event: OrderEvent):
        self.debug(f"Unexpected exercise or assignment: {assignment_event}")
        self.blocked_dates.add(self.time.date())
        self._check_equity_from_assignment(self.time.date())

    def _check_equity_from_assignment(self, today):
