        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.current_bucket = None
        self.bucket_bars = {}

        self.held_option = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None

        self.no_entry_today = False
        self.expiration_processed_date = None

    def OnData(self, slice: Slice):
        local_time = self.Time
        current_date = local_time.date()

        self._liquidate_unexpected_spy_position()

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if current_date >= expiry_date:
                self.no_entry_today = True
                self._liquidate_at_expiration_processing()

            if self.held_option is not None:
                self._evaluate_option_exit(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        # Only regular-session minute bars are used.
        if not (local_time.hour == 9 and local_time.minute >= 31) and not (
            10 <= local_time.hour < 16
        ) and not (local_time.hour == 16 and local_time.minute == 0):
            return

        bucket_end = self._bucket_end(local_time)

        if self.current_bucket is None:
            self.current_bucket = bucket_end
        elif bucket_end != self.current_bucket:
            self._flush_bucket()
            self.current_bucket = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[local_time.replace(second=0, microsecond=0)] = spy_bar

    def _bucket_end(self, time_value):
        midnight = datetime(
            time_value.year, time_value.month, time_value.day
        )
        minutes = time_value.hour * 60 + time_value.minute
        end_minutes = ((minutes + 4) // 5) * 5
        return midnight + timedelta(minutes=end_minutes)

    def _flush_bucket(self):
        if self.current_bucket is None:
            return

        end_time = self.current_bucket
        expected = [
            (end_time - timedelta(minutes=i)).replace(second=0, microsecond=0)
            for i in range(4, -1, -1)
        ]

        # Missing minute data means the five-minute bar is missing.
        if any(moment not in self.bucket_bars for moment in expected):
            return

        bars = [self.bucket_bars[moment] for moment in expected]
        self._process_five_minute_close(end_time, bars[-1].Close)

    def _process_five_minute_close(self, end_time, close):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None
        previous_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        bar_time = end_time.time()
        eligible_time = datetime.strptime("09:45", "%H:%M").time() <= bar_time <= \
            datetime.strptime("14:30", "%H:%M").time()

        if bullish_cross and eligible_time:
            self._try_enter_option(end_time.date(), close)

    def _try_enter_option(self, current_date, spy_price):
        if self.no_entry_today:
            return

        if self.held_option is not None or self.entry_order_id is not None:
            return

        chains = list(self.CurrentSlice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()

                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying expiration or call.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)

        strike_floor = float(spy_price) * 1.01
        selected = [
            contract for contract in candidates
            if (
                contract.Expiry.date() == nearest_expiry
                and float(contract.Strike) >= strike_floor
            )
        ]

        if not selected:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))

        contract = selected[0]
        ticket = self.MarketOrder(
            contract.Symbol,
            1,
            tag="Bullish five-minute MA crossover entry"
        )

        self.entry_order_id = ticket.OrderId
        self.Debug(f"Entry submitted: {contract.Symbol}")

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_order_id is not None:
            return

        quote = slice.QuoteBars.get(self.held_option.Symbol)

        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0

                if midpoint >= 1.50 * float(self.entry_price):
                    self._submit_exit("50% profit target")
                    return

        expiry_date = self.held_option.ID.Date.date()
        prior_trading_day = self._prior_trading_day(expiry_date)

        if (
            self.Time.date() == prior_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("expiration time stop")

    def _submit_exit(self, reason):
        if self.held_option is None or self.exit_order_id is not None:
            return

        if self.entry_order_id is not None:
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity <= 0:
