            self.no_entry_today = False

        # Never intentionally retain equity received through exercise/assignment.
        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_today = True
            self.Debug(
                f"{self.Time}: unexpected SPY equity position detected; liquidating"
            )
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

        # Expiration processing takes precedence over all entries.
        if self.held_option and self.expiration_date:
            if today >= self.expiration_date:
                self.no_entry_today = True
                self._liquidate_option("expiration")

        bar = slice.Bars.get(self.spy)
        if bar:
            self._update_five_minute_bar(bar, slice)

        # Evaluate option exits on every minute Slice.
        self._evaluate_exits(slice)

    def _update_five_minute_bar(self, bar: TradeBar, slice: Slice):
        t = bar.Time

        if t.time() < time(9, 30) or t.time() >= time(16, 0):
            return

        minutes = (t.hour * 60 + t.minute) - (9 * 60 + 30)
        interval_start = datetime(
            t.year, t.month, t.day, 9, 30
        ) + timedelta(minutes=(minutes // 5) * 5)

        if self.interval_start is None:
            self.interval_start = interval_start

        if interval_start != self.interval_start:
            self._finish_interval(slice)
            self.interval_start = interval_start
            self.interval_bars = {}

        self.interval_bars[t] = bar

    def _finish_interval(self, slice: Slice):
        if self.interval_start is None:
            return

        expected = [
            self.interval_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # Missing minute data invalidates the entire five-minute bar.
        if not all(t in self.interval_bars for t in expected):
            self.interval_bars = {}
            return

        bars = [self.interval_bars[t] for t in expected]
        close = bars[-1].Close

        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            self.previous_fast = None
            self.previous_slow = None
            self.interval_bars = {}
            return

        fast = sum(list(self.fast_window)[-5:]) / 5.0
        slow = sum(self.slow_window) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        completed_at = self.interval_start + timedelta(minutes=5)
        eligible_time = time(9, 45) <= completed_at.time() <= time(14, 30)

        self.previous_fast = fast
        self.previous_slow = slow
        self.interval_bars = {}

        if bullish and eligible_time:
            self._try_enter(slice, completed_at)

    def _try_enter(self, slice: Slice, completed_at: datetime):
        if self.no_entry_today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket and self._order_is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if not chain:
            self.Debug(f"{completed_at}: skipped entry; no option chain")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"{completed_at}: skipped entry; invalid SPY price")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expirations = sorted({
            c.Symbol.ID.Date.date()
            for c in contracts
            if c.Symbol.ID.Date.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug(f"{completed_at}: skipped entry; no valid expiration")
            return

        expiration = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            c for c in contracts
            if c.Symbol.ID.Date.date() == expiration
            and c.Symbol.ID.OptionRight == OptionRight.Call
            and c.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{completed_at}: skipped entry; no qualifying call for "
                f"{expiration}"
            )
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"{completed_at}: submitted 1-call market entry "
            f"{selected.Symbol}"
        )

    def _evaluate_exits(self, slice: Slice):
        if not self.held_option or not self.entry_price:
            return

        if self.expiration_date:
            previous_trading_day = self._previous_trading_day(
                self.expiration_date
            )

            if (
                self.Time.date() == previous_trading_day
                and self.Time.time() >= time(15, 45)
            ):
                self._liquidate_option("time stop")
                return

        quote = slice.QuoteBars.get(self.held_option)
        if not quote or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason: str):
        if not self.held_option:
            return

        if self.exit_ticket and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

        self.Debug(
            f"{self.Time}: submitted option liquidation for {reason}: "
            f"{self.held_option}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = order_event.Symbol.ID.Date.date()

                self.Debug(
                    f"{self.Time}: entry filled {self.held_option} "
                    f"at {self.entry_price}"
                )

            elif (
                self.exit_ticket
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"{self.Time}: option exit filled at "
                    f"{order_event.FillPrice}"
                )
                self.held_option = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None
                self.entry_ticket = None

        order_type = str(order_event.OrderType)
        if "OptionExercise" in order_type or "OptionAssignment" in order_type:
            self.no_entry_today = True
            self.Debug(
                f"{self.Time}: unexpected exercise/assignment event; "
                f"liquidating SPY equity"
            )
            self._liquidate_unexpected_equity()

    def OnAssignmentOrderEvent(self, assignment_event):
        self.no_entry_today = True
        self.Debug(
            f"{self.Time}: unexpected option assignment; "
            f"liquidating SPY equity"
        )
        self._liquidate_unexpected_equity()

    def _liquidate_unexpected_equity(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise/assignment cleanup"
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _order_is_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )
