            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        )
        self.spy_symbol = self.spy.symbol

        self.spy_options = self.add_option("SPY", Resolution.MINUTE)
        self.spy_options.set_filter(
            lambda universe: universe
                .include_weeklys()
                .expiration(7, 730)
                .strikes(-200, 200)
        )

        self._bucket_date = None
        self._bucket_end = None
        self._bucket_bars = []

        self._closes = []

        self._entry_order_id = None
        self._held_symbol = None
        self._entry_price = None

        self._exit_order_id = None
        self._equity_liquidation_order_id = None
        self._no_entry_date = None

    def on_data(self, slice: Slice):
        current_date = self.time.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()
        self._evaluate_option_exit(slice)

        spy_bar = slice.bars.get(self.spy_symbol)
        if spy_bar is not None:
            self._update_five_minute_bucket(spy_bar, slice)

    def _update_five_minute_bucket(self, minute_bar, slice: Slice):
        bar_end = minute_bar.end_time
        local_date = bar_end.date()

        if bar_end.time() < time(9, 31) or bar_end.time() > time(16, 0):
            return

        session_start = bar_end.replace(
            hour=9, minute=30, second=0, microsecond=0
        )

        minutes_since_start = int(
            (bar_end - session_start).total_seconds() // 60
        )

        if minutes_since_start < 1:
            return

        bucket_number = (minutes_since_start - 1) // 5
        bucket_end = session_start + timedelta(
            minutes=(bucket_number + 1) * 5
        )

        if self._bucket_end != bucket_end or self._bucket_date != local_date:
            if self._bucket_end is not None:
                self._finish_bucket(slice)

            self._bucket_date = local_date
            self._bucket_end = bucket_end
            self._bucket_bars = []

        self._bucket_bars.append(minute_bar)

        if bar_end == self._bucket_end:
            self._finish_bucket(slice)
            self._bucket_date = None
            self._bucket_end = None
            self._bucket_bars = []

    def _finish_bucket(self, slice: Slice):
        if self._bucket_end is None:
            return

        expected_ends = [
            self._bucket_end - timedelta(minutes=4),
            self._bucket_end - timedelta(minutes=3),
            self._bucket_end - timedelta(minutes=2),
            self._bucket_end - timedelta(minutes=1),
            self._bucket_end,
        ]

        actual_ends = [bar.end_time for bar in self._bucket_bars]

        # Do not synthesize a bar when any minute is missing.
        if len(actual_ends) != 5 or actual_ends != expected_ends:
            return

        close = self._bucket_bars[-1].close
        previous_count = len(self._closes)

        previous_fast = None
        previous_slow = None

        if previous_count >= 5:
            previous_fast = sum(self._closes[-5:]) / 5

        if previous_count >= 20:
            previous_slow = sum(self._closes[-20:]) / 20

        self._closes.append(close)

        if len(self._closes) > 20:
            self._closes.pop(0)

        if previous_fast is None or previous_slow is None:
            return

        current_fast = sum(self._closes[-5:]) / 5
        current_slow = sum(self._closes[-20:]) / 20

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = self._bucket_end.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._evaluate_entry(slice)

    def _evaluate_entry(self, slice: Slice):
        if self._no_entry_date == self.time.date():
            return

        if self._held_symbol is not None:
            return

        if self._entry_order_id is not None:
            return

        chain = slice.option_chains.get(self.spy_options.symbol)
        if chain is None:
            self.debug(f"{self.time}: skipped entry; no option chain")
            return

        current_spy_price = self.securities[self.spy_symbol].price
        if current_spy_price <= 0:
            self.debug(f"{self.time}: skipped entry; invalid SPY price")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)

        contracts = list(chain.contracts.values())
        expirations = sorted({
            contract.symbol.id.date.date()
            for contract in contracts
            if contract.symbol.id.option_right == OptionRight.CALL
            and contract.symbol.id.date.date() >= minimum_expiry
        })

        if not expirations:
            self.debug(f"{self.time}: skipped entry; no valid expiration")
            return

        selected_expiry = expirations[0]
        minimum_strike = current_spy_price * Decimal("1.01")

        candidates = [
            contract
            for contract in contracts
            if contract.symbol.id.option_right == OptionRight.CALL
            and contract.symbol.id.date.date() == selected_expiry
            and contract.symbol.id.strike_price >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"{self.time}: skipped entry; no qualifying call "
                f"for {selected_expiry}"
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                contract.symbol.id.strike_price,
                str(contract.symbol)
            )
        )[0]

        ticket = self.market_order(selected.symbol, 1)

        if ticket is not None:
            self._entry_order_id = ticket.order_id
            self.debug(
                f"{self.time}: submitted entry for {selected.symbol}"
            )

    def _evaluate_option_exit(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        if self._exit_order_id is not None:
            return

        quote = slice.quote_bars.get(self._held_symbol)
        if quote is None:
            return

        bid = quote.bid.close if quote.bid is not None else 0
        ask = quote.ask.close if quote.ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if midpoint >= self._entry_price * Decimal("1.50"):
            self._submit_option_exit("50% profit target")

    def _handle_expiration_processing(self):
        if self._held_symbol is None:
            return

        expiry_date = self._held_symbol.id.date.date()
        current_date = self.time.date()

        if current_date >= expiry_date:
            self._no_entry_date = current_date
            self._submit_option_exit("expiration processing")

    def _submit_option_exit(self, reason):
