        spy_bar = slice.bars.get(self.spy_symbol)
        if spy_bar is not None:
            self._update_five_minute_bucket(spy_bar, slice)

    def _update_five_minute_bucket(self, minute_bar, slice: Slice):
        bar_end = minute_bar.end_time
        local_date = bar_end.date()

        if bar_end.time() < time(9, 31) or bar_end.time() > time(16, 0):
            return

        session_start = bar_end.replace(
            hour=9, minute=30, second=0, microsecond=0
        )

        minutes_since_start = int(
            (bar_end - session_start).total_seconds() // 60
        )

        if minutes_since_start < 1:
            return

        bucket_number = (minutes_since_start - 1) // 5
        bucket_end = session_start + timedelta(
            minutes=(bucket_number + 1) * 5
        )

        if self._bucket_end != bucket_end or self._bucket_date != local_date:
            if self._bucket_end is not None:
                self._finish_bucket(slice)

            self._bucket_date = local_date
            self._bucket_end = bucket_end
            self._bucket_bars = []

        self._bucket_bars.append(minute_bar)

        if bar_end == self._bucket_end:
            self._finish_bucket(slice)
            self._bucket_date = None
            self._bucket_end = None
            self._bucket_bars = []

    def _finish_bucket(self, slice: Slice):
        if self._bucket_end is None:
            return

        expected_ends = [
            self._bucket_end - timedelta(minutes=4),
            self._bucket_end - timedelta(minutes=3),
            self._bucket_end - timedelta(minutes=2),
            self._bucket_end - timedelta(minutes=1),
            self._bucket_end,
        ]

        actual_ends = [bar.end_time for bar in self._bucket_bars]

        # Do not synthesize a bar when any minute is missing.
        if len(actual_ends) != 5 or actual_ends != expected_ends:
            return

        close = self._bucket_bars[-1].close
        previous_count = len(self._closes)

        previous_fast = None
        previous_slow = None

        if previous_count >= 5:
            previous_fast = sum(self._closes[-5:]) / 5

        if previous_count >= 20:
            previous_slow = sum(self._closes[-20:]) / 20

        self._closes.append(close)

        if len(self._closes) > 20:
            self._closes.pop(0)

        if previous_fast is None or previous_slow is None:
            return

        current_fast = sum(self._closes[-5:]) / 5
        current_slow = sum(self._closes[-20:]) / 20

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = self._bucket_end.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._evaluate_entry(slice)

