        if slice.Bars.ContainsKey(self.spy):
            minute_bar = slice.Bars[self.spy]
            bucket = self.GetFiveMinuteBucket(minute_bar.EndTime)

            previous_end = self.minute_bucket_last_end.get(bucket)
            if previous_end is not None:
                if minute_bar.EndTime != previous_end + timedelta(minutes=1):
                    self.invalid_buckets.add(bucket)

            self.minute_bucket_last_end[bucket] = minute_bar.EndTime
            self.consolidator.Update(minute_bar)

        self.HandleExpirationAndTimeStop()
        self.HandleProfitTarget(slice)

    def GetFiveMinuteBucket(self, value):
        value = value.replace(second=0, microsecond=0)
        return value.replace(
            minute=value.minute - (value.minute % 5)
        )

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        bucket = self.GetFiveMinuteBucket(bar.EndTime)

        if bucket in self.invalid_buckets:
            self.invalid_buckets.discard(bucket)
            self.minute_bucket_last_end.pop(bucket, None)
            return

        self.minute_bucket_last_end.pop(bucket, None)

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_time = bar.EndTime.time()
        if not (
            datetime(2000, 1, 1, 9, 45).time()
            <= bar_time
            <= datetime(2000, 1, 1, 14, 30).time()
        ):
            return

        if bullish_crossover:
            self.TryEnter(bar.Close, bar.EndTime.date())

    def TryEnter(self, spy_price, signal_date):
        if self.held_symbol is not None:
            return

        if self.EntryOrderIsOpen():
            return

        if self.blocked_entry_date == signal_date:
            return

        chains = list(self.current_slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for chain in chains
            for contract in chain.Contracts.Values
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least 7 days out")
            return

        selected_expiry = eligible_expiries[0]

        candidates = [
            contract
            for chain in chains
            for contract in chain.Contracts.Values
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        selected_contract = sorted(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected_contract.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )

        self.Debug("Entry submitted: {}".format(selected_contract.Symbol))

    def EntryOrderIsOpen(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def ExitOrderIsOpen(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def HandleProfitTarget(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        quote = self.GetCurrentQuote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint < 1.50 * self.entry_price:
            return

        if self.ExitOrderIsOpen():
            self.exit_ticket.Cancel("Replacing exit with profit-target exit")
            self.exit_ticket = None

        self.SubmitExit("50% profit target")

    def HandleExpirationAndTimeStop(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.blocked_entry_date = today
            self.SubmitExit("expiration safeguard")
            return

        if (
            self.Time.hour == 15
            and self.Time.minute >= 45
            and self.last_time_stop_date != today
        ):
            next_trading_day = today + timedelta(days=1)
            exchange_hours = self.Securities[self.spy].Exchange.Hours

            while not exchange_hours.IsDateOpen(next_trading_day):
                next_trading_day += timedelta(days=1)

            if next_trading_day == expiry_date:
                self.last_time_stop_date = today
                self.SubmitExit("pre-expiration time stop")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.ExitOrderIsOpen():
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {} ({})".format(
                self.held_symbol,
                reason
            )
        )

    def GetCurrentQuote(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            if chain.Contracts.ContainsKey(symbol):
                contract = chain.Contracts[symbol]
                return contract.BidPrice, contract.AskPrice

        return None

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_symbol = self.entry_ticket.Symbol
            self.entry_price = order_event.FillPrice

            self.Debug(
                "Entry filled: {} at {:.4f}".format(
                    self.held_symbol,
                    self.entry_price
                )
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {} at {:.4f}".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )

            if (
                self.held_symbol is not None
                and self.Portfolio[self.held_symbol].Quantity == 0
            ):
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.blocked_entry_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment; liquidating SPY equity")

            spy_quantity = self.Portfolio[self.spy].Quantity
            if spy_quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -spy_quantity,
                    tag="Exercise or assignment safeguard"
                )
