from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone("America/New_York")

        equity = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        )
        self.spy = equity.symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        self.option = option.symbol

        # Broad universe so the required expiration and strike can be present.
        option.set_filter(
            lambda universe: universe
                .include_weeklys()
                .strikes(-200, 200)
                .expiration(0, 730)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = {}
        self.bucket_invalid = False

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def on_data(self, slice: Slice):
        current_date = self.time.date()

        # Handle expiration processing before evaluating any new signal.
        if self.held_option is not None:
            expiry_date = self._expiry_date(self.held_option)
            if expiry_date is not None and current_date >= expiry_date:
                self.no_entry_date = current_date
                self._submit_exit("expiration processing")

        # Exercise/assignment can create underlying shares.
        spy_quantity = self.portfolio[self.spy].quantity
        if spy_quantity != 0 and self.held_option is None:
            self.debug(
                f"{self.time}: unexpected SPY position from exercise/assignment; "
                f"liquidating {spy_quantity} shares"
            )
            self.market_order(self.spy, -spy_quantity)

        # Exits are evaluated on every minute Slice.
        self._check_exits(slice)

        spy_bar = slice.bars.get(self.spy)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        bar_time = minute_bar.end_time
        bar_date = bar_time.date()
        bar_clock = bar_time.time()

        session_start = datetime(
            bar_date.year, bar_date.month, bar_date.day, 9, 30
        )
        session_end = datetime(
            bar_date.year, bar_date.month, bar_date.day, 16, 0
        )

        if bar_time < session_start or bar_time > session_end:
            return

        # TradeBar.Time is the minute's start time; EndTime identifies the
        # five-minute boundary. Use the minute start for bucket alignment.
        minute_start = minute_bar.time
        if minute_start < session_start:
            return

        elapsed_minutes = int((minute_start - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

        if self.bucket_date != bar_date or self.bucket_start != bucket_start:
            if (
                self.bucket_start is not None
                and not self.bucket_invalid
                and len(self.bucket_bars) == 5
            ):
                self._consume_five_minute_bar(slice)

            self.bucket_date = bar_date
            self.bucket_start = bucket_start
            self.bucket_bars = {}
            self.bucket_invalid = False

        minute_offset = int(
            (minute_start - self.bucket_start).total_seconds() // 60
        )

        if minute_offset not in range(5):
            self.bucket_invalid = True
            return

        if minute_offset in self.bucket_bars:
            self.bucket_invalid = True
            return

        # A five-minute bar is invalid if its first minute was missing.
        if len(self.bucket_bars) == 0 and minute_offset != 0:
            self.bucket_invalid = True

        self.bucket_bars[minute_offset] = minute_bar

        # Emit the completed bar when its fifth minute arrives.
        if minute_offset == 4:
            if not self.bucket_invalid and len(self.bucket_bars) == 5:
                self._consume_five_minute_bar(slice)

            self.bucket_start = None
            self.bucket_bars = {}
            self.bucket_invalid = False

    def _consume_five_minute_bar(self, slice: Slice):
        bars = [self.bucket_bars[i] for i in range(5)]

        close = bars[-1].close
        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        fast = sum(list(self.closes)[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        completed_end = bars[-1].end_time
        eligible_time = (
            datetime.combine(completed_end.date(), completed_end.time()).time()
            >= datetime.strptime("09:45", "%H:%M").time()
            and datetime.combine(completed_end.date(), completed_end.time()).time()
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        if bullish_cross and eligible_time:
            self._try_enter(slice, float(close), completed_end.date())

        self.previous_fast = fast
        self.previous_slow = slow

    def _try_enter(self, slice: Slice, spy_price: float, signal_date):
        if signal_date == self.no_entry_date:
            return

        if self.held_option is not None or self.entry_order_id is not None:
            return

        chain = slice.option_chains.get(self.option)
        if chain is None:
            self.debug(f"{self.time}: skipped entry; no option chain")
            return

        minimum_expiry = signal_date + timedelta(days=7)
        contracts = list(chain.contracts.values())

        expirations = sorted({
            self._expiry_date(contract)
            for contract in contracts
            if self._expiry_date(contract) is not None
            and self._expiry_date(contract) >= minimum_expiry
        })

        if not expirations:
            self.debug(f"{self.time}: skipped entry; no valid expiration")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if self._expiry_date(contract) == selected_expiry
            and contract.right == OptionRight.CALL
            and float(contract.strike) >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"{self.time}: skipped entry; no qualifying call at "
                f"{selected_expiry}"
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.strike),
                str(contract.symbol)
            )
        )

        ticket = self.market_order(
            selected.symbol,
            1,
            tag="bullish five-minute crossover"
        )
        self.entry_order_id = ticket.order_id

        self.debug(
            f"{self.time}: submitted entry for {selected.symbol}; "
            f"SPY={spy_price:.2f}"
        )

    def _check_exits(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.portfolio[self.held_option].quantity
        if quantity <= 0:
            return

        expiry_date = self._expiry_date(self.held_option)
        current_date = self.time.date()

        if expiry_date is not None:
            prior_trading_day = self._prior_trading_day(expiry_date)
            if (
                current_date == prior_trading_day
                and self.time.time() >= datetime.strptime(
                    "15:45", "%H:%M"
                ).time()
            ):
                self._submit_exit("expiration time stop")
                return

        quote = self._current_quote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _current_quote(self, slice: Slice, symbol):
        for chain in slice.option_chains.values():
            contract = chain.contracts.get(symbol)
            if contract is not None:
                return float(contract.bid_price), float(contract.ask_price)

        quote_bar = slice.quote_bars.get(symbol)
        if quote_bar is not None:
            return float(quote_bar.bid.close), float(quote_bar.ask.close)

        return None

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.portfolio[self.held_option].quantity
        if quantity <= 0:
            return

        if self.exit_order_id is not None:
            ticket = self.transactions.get_order_ticket(self.exit_order_id)
            if ticket is not None and not ticket.status.is_closed():
                ticket.cancel("replaced by liquidation exit")

        ticket = self.market_order(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.exit_order_id = ticket.order_id
        self.debug(
            f"{self.time}: submitted exit for {self.held_option}; reason={reason}"
        )

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status == OrderStatus.FILLED:
            if order_event.order_id == self.entry_order_id:
                self.held_option = order_event.symbol
                self.entry_price = float(order_event.fill_price)
                self.entry_order_id = None
                self.debug(
                    f"{self.time}: entry filled {self.held_option}; "
                    f"price={self.entry_price:.4f}"
                )

            elif order_event.order_id == self.exit_order_id:
                self.debug(
                    f"{self.time}: exit filled {order_event.symbol}; "
                    f"price={order_event.fill_price:.4f}"
                )
                self.exit_order_id = None
                self.held_option = None
                self.entry_price = None

        elif order_event.status in (
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        ):
            if order_event.order_id == self.entry_order_id:
                self.debug(
                    f"{self.time}: entry order was not filled; "
                    f"status={order_event.status}"
                )
                self.entry_order_id = None

            if order_event.order_id == self.exit_order_id:
                self.exit_order_id = None

    def on_assignment_order_event(self, assignment_event: OrderEvent):
        self.debug(
            f"{self.time}: unexpected option exercise/assignment: "
            f"{assignment_event}"
        )

        spy_quantity = self.portfolio[self.spy].quantity
        if spy_quantity != 0:
            self.market_order(self.spy, -spy_quantity)

    def _expiry_date(self, contract_or_symbol):
        try:
            expiry = contract_or_symbol.expiry
        except AttributeError:
            try:
                expiry = contract_or_symbol.id.date
            except AttributeError:
                return None

        try:
            return expiry.date()
        except AttributeError:
            return expiry

    def _prior_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.securities[self.spy].exchange.hours

        while not exchange_hours.is_date_open(candidate):
            candidate -= timedelta(days=1)

        return candidate
