from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.current_bucket_end = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_fill_price = None

        self.block_entries_date = None
        self.last_equity_handling_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Handle unexpected equity created by exercise or assignment.
        if self.Portfolio[self.spy].Quantity != 0:
            if self.last_equity_handling_date != current_date:
                self.Debug(
                    f"{self.Time}: Unexpected SPY equity position detected; "
                    "liquidating immediately."
                )
                self.last_equity_handling_date = current_date
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity
            )
            self.block_entries_date = current_date

        self._process_expiration_safety(current_date)

        # Build the five-minute bar from actual minute bars.
        if self.spy in slice.Bars:
            signal = self._process_minute_bar(slice.Bars[self.spy])
            if signal:
                self._try_enter(slice)

        # Manage exits on every minute Slice.
        self._evaluate_option_exit(slice)

    def _process_minute_bar(self, bar):
        local_time = self.Time
        local_date = local_time.date()
        minute_of_day = local_time.hour * 60 + local_time.minute

        # Regular session only.
        if minute_of_day < 570 or minute_of_day > 960:
            return False

        bucket_end_minute = ((local_time.minute + 4) // 5) * 5
        bucket_end = local_time.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=local_time.hour * 60 + bucket_end_minute)

        # Start a new bucket, finalizing the previous one if necessary.
        if self.current_bucket_end != bucket_end:
            signal = self._finalize_bucket()
            self.current_bucket_end = bucket_end
            self.current_bucket_bars = {}
        else:
            signal = False

        # Only retain one actual minute bar per minute.
        self.current_bucket_bars[local_time.minute] = bar

        # A signal can only be generated when the completed bucket is
        # finalized by the next minute or at the end of the data stream.
        return signal

    def _finalize_bucket(self):
        if self.current_bucket_end is None:
            return False

        bucket_end = self.current_bucket_end
        expected_minutes = {
            (bucket_end - timedelta(minutes=i)).minute
            for i in range(1, 6)
        }

        # Missing minute data means the five-minute bar is missing.
        if set(self.current_bucket_bars.keys()) != expected_minutes:
            self.current_bucket_bars = {}
            return False

        bars = [
            self.current_bucket_bars[m]
            for m in sorted(self.current_bucket_bars.keys())
        ]
        close = float(bars[-1].Close)

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            self.current_bucket_bars = {}
            return False

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.current_bucket_bars = {}

        eligible_time = (
            bucket_end.hour > 9 or
            (bucket_end.hour == 9 and bucket_end.minute >= 45)
        ) and (
            bucket_end.hour < 14 or
            (bucket_end.hour == 14 and bucket_end.minute <= 30)
        )

        return (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow and
            eligible_time
        )

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if self.block_entries_date == current_date:
            return

        if self._has_option_holding():
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
