            return

        chain = slice.OptionChains[self.option.Symbol]
        today = current_date
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Skipped entry; no eligible expiration.")
            return

        selected_expiry = eligible_expiries[0]
        spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug(f"{self.Time}: Skipped entry; invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Skipped entry; no qualifying call for "
                f"{selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.held_option = selected.Symbol
        self.entry_fill_price = None

        self.Debug(
            f"{self.Time}: Entry submitted for {selected.Symbol}."
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        expiry = self.held_option.ID.Date.date()
        current_date = self.Time.date()

        # Never intentionally hold through expiration.
        if current_date >= expiry:
            self.block_entries_date = current_date
            self._submit_exit("expiration safety")
            return

        # Time stop at 15:45 on the immediately preceding trading day.
        if (
            self.Time.hour == 15 and
            self.Time.minute >= 45 and
            self._is_immediately_before_expiration(current_date, expiry)
        ):
            self._submit_exit("time stop")
            return

        # Profit target requires a strictly positive current bid and ask.
        midpoint = self._current_midpoint(slice, self.held_option)
        if midpoint is None or self.entry_fill_price is None:
            return

        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit("profit target")

    def _current_midpoint(self, slice: Slice, symbol):
        if symbol in slice.QuoteBars:
            quote = slice.QuoteBars[symbol]
            bid = quote.Bid.Close if quote.Bid is not None else None
            ask = quote.Ask.Close if quote.Ask is not None else None

            if bid is not None and ask is not None:
                bid = float(bid)
                ask = float(ask)
                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

        if self.option.Symbol in slice.OptionChains:
            for contract in slice.OptionChains[self.option.Symbol]:
                if contract.Symbol != symbol:
                    continue

                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

        return None

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        # Cancel any other open exit order before submitting this market order.
        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )

        self.Debug(
            f"{self.Time}: Exit submitted ({reason}) for "
            f"{self.held_option}."
        )

    def _process_expiration_safety(self, current_date):
        if self.held_option is None:
            return

        expiry = self.held_option.ID.Date.date()
        if current_date >= expiry:
            self.block_entries_date = current_date
            self._submit_exit("expiration processing")

    def _is_immediately_before_expiration(self, current_date, expiry):
        test_date = current_date + timedelta(days=1)

        while test_date < expiry:
            test_date += timedelta(days=1)

        return test_date == expiry

    def _has_option_holding(self):
        for security in self.Securities.Values:
            if security.Symbol.SecurityType != SecurityType.Option:
                continue

            if security.Holdings.Invested:
                return True

        return False

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        status = ticket.Status
        return status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"{self.Time}: Entry filled at "
                    f"{self.entry_fill_price:.4f}."
                )

            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_ticket = None
                self.held_option = None
                self.entry_fill_price = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                f"{self.Time}: Exit filled for {order_event.Symbol}."
            )
            self.exit_ticket = None
            self.entry_ticket = None
            self.held_option = None
            self.entry_fill_price = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                f"{self.Time}: Unexpected option exercise or assignment "
                f"event for {order_event.Symbol}."
            )

            if self.Portfolio[self.spy].Quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity
                )

            self.block_entries_date = self.Time.date()
