from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_end = None
        self.current_minutes = {}

        self.entry_ticket = None
        self.held_option = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entries_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_expiration(today)

        if self.spy in slice.Bars:
            self._consume_minute_bar(slice.Bars[self.spy], slice)

        self._evaluate_option_exit(slice)

    def _consume_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        local_date = end_time.date()
        end_clock = end_time.time()

        if end_clock < time(9, 31) or end_clock > time(16, 0):
            return

        minutes_from_open = (
            end_time.hour * 60 + end_time.minute
            - (9 * 60 + 30)
        )

        if minutes_from_open <= 0:
            return

        bucket_index = (minutes_from_open - 1) // 5
        bucket_end = datetime.combine(
            local_date,
            time(9, 35)
        ) + timedelta(minutes=5 * bucket_index)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.current_minutes = {}

        self.current_minutes[end_time] = bar

        if end_time != bucket_end:
            return

        if len(self.current_minutes) == 5:
            closes = [
                self.current_minutes[t].Close
                for t in sorted(self.current_minutes)
            ]

            consolidated_close = closes[-1]
            self._update_averages_and_check_signal(
                consolidated_close,
                bucket_end,
                slice
            )

        self.current_bucket_end = None
        self.current_minutes = {}

    def _update_averages_and_check_signal(
        self,
        close: float,
        bar_end: datetime,
        slice: Slice
    ):
        current_fast = None
        current_slow = None

        if len(self.fast_closes) == self.fast_closes.maxlen:
            current_fast = sum(self.fast_closes) / len(self.fast_closes)

        if len(self.slow_closes) == self.slow_closes.maxlen:
            current_slow = sum(self.slow_closes) / len(self.slow_closes)

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) >= 5:
            current_fast = sum(self.fast_closes) / len(self.fast_closes)

        if len(self.slow_closes) >= 20:
            current_slow = sum(self.slow_closes) / len(self.slow_closes)

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_crossover:
            return

        if not (
            time(9, 45) <= bar_end.time() <= time(14, 30)
        ):
            return

        self._try_enter(slice, bar_end.date())

    def _try_enter(self, slice: Slice, algorithm_date):
        if self.no_entries_date == algorithm_date:
            return

        if self.held_option is not None:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        selected_expiry = expirations[0]
        spy_price = float(slice.Bars[self.spy].Close)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} strike {:.2f} expiry {}".format(
                selected.Symbol,
                float(selected.Strike),
                selected_expiry
            )
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested or holding.Quantity <= 0:
            return

        expiration_date = self.held_option.ID.Date.date()
        today = self.Time.date()

        if today >= expiration_date:
            self.no_entries_date = today
            self._submit_exit("expiration processing")
            return

        if (
            self.Time.time() >= time(15, 45)
            and today == self._preceding_trading_day(expiration_date)
        ):
            self._submit_exit("expiration time stop")
            return

        if self.held_option not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_option]
        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        ):
            self._submit_exit("50 percent profit target", cancel_existing=True)

    def _submit_exit(self, reason: str, cancel_existing: bool = False):
        if self.held_option is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            if not cancel_existing:
                return

            self.exit_ticket.Cancel("Replacing exit order")
            self.exit_ticket = None

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted for {}: {}".format(
                self.held_option,
                reason
            )
        )

    def _process_expiration(self, today):
        if self.held_option is None:
            return

        expiration_date = self.held_option.ID.Date.date()
        if today >= expiration_date:
            self.no_entries_date = today
            self._submit_exit("expiration processing")

    def _preceding_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]

        if holding.Invested and holding.Quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating."
            )
            self.Liquidate(
                self.spy,
                tag="Unexpected exercise or assignment handling"
            )
            self.no_entries_date = self.Time.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_option,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {} at {:.4f}".format(
                    order_event.Symbol,
                    float(order_event.FillPrice)
                )
            )
            self.exit_ticket = None
            self.held_option = None
            self.entry_price = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        self.Debug(
            "Unexpected option exercise or assignment detected; "
            "liquidating SPY."
        )
        self.Liquidate(
            self.spy,
            tag="Unexpected exercise or assignment handling"
        )
        self.no_entries_date = self.Time.date()

    @staticmethod
    def _ticket_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.CancelSubmitted
        )
