        self.ProcessMinuteBar(spy_bar, slice)

    def ProcessMinuteBar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time.replace(second=0, microsecond=0)
        session_start = bar_time.replace(hour=9, minute=30)

        if bar_time < session_start or bar_time >= bar_time.replace(
            hour=16, minute=0
        ):
            return

        minutes_from_open = int((bar_time - session_start).total_seconds() // 60)
        current_bucket = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )

        if self.bucket_start is not None and current_bucket != self.bucket_start:
            self.CompleteFiveMinuteBar(slice)

        if self.bucket_start != current_bucket:
            self.bucket_start = current_bucket
            self.bucket_closes = {}

        self.bucket_closes[bar_time] = float(bar.Close)

        if len(self.bucket_closes) == 5:
            self.CompleteFiveMinuteBar(slice)

    def CompleteFiveMinuteBar(self, slice: Slice):
        if self.bucket_start is None:
            return

        start = self.bucket_start
        expected_times = [
            start + timedelta(minutes=i) for i in range(5)
        ]

        if all(t in self.bucket_closes for t in expected_times):
            close = self.bucket_closes[expected_times[-1]]
            bar_end = start + timedelta(minutes=5)

            prior_fast = self.previous_fast
            prior_slow = self.previous_slow

            self.fast.Update(bar_end, close)
            self.slow.Update(bar_end, close)

            bullish_cross = (
                prior_fast is not None
                and prior_slow is not None
                and self.fast.IsReady
                and self.slow.IsReady
                and prior_fast <= prior_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

            if (
                bullish_cross
                and datetime(2000, 1, 1, 9, 45).time()
                <= bar_end.time()
                <= datetime(2000, 1, 1, 14, 30).time()
            ):
                self.TryEnter(slice, close)

        self.bucket_start = None
        self.bucket_closes = {}

