from AlgorithmImports import *
from collections import deque
from datetime import datetime, time, timedelta
from decimal import Decimal


class SpyLongCallCrossover(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone("America/New_York")

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        self.option = self.add_option("SPY", Resolution.MINUTE)
        self.option.set_filter(
            lambda universe: universe
                .include_weeklys()
                .strikes(-500, 500)
                .expiration(0, 365)
        )
        self.option_symbol = self.option.symbol

        self.consolidator = TradeBarConsolidator(
            timedelta(minutes=5),
            timedelta(hours=9, minutes=30)
        )
        self.consolidator.data_consolidated += self._on_five_minute_bar

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.minute_counts = {}

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None

        self.held_option = None
        self.entry_price = None
        self.expiry_date = None
        self.no_entry_today = False
        self.last_day = None

    def on_data(self, slice: Slice):
        self.current_slice = slice

        if self.last_day != self.time.date():
            self.last_day = self.time.date()
            self.no_entry_today = False

        self._handle_unexpected_equity_position()

        spy_bar = slice.bars.get(self.spy)
        if spy_bar is not None:
            if self._is_regular_session(spy_bar.time):
                slot = self._five_minute_slot(spy_bar.time)
                self.minute_counts[slot] = self.minute_counts.get(slot, 0) + 1
                self.consolidator.update(spy_bar)

        if self.held_option is not None:
            self._process_held_option(slice)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        expected_count = self.minute_counts.get(bar.time, 0)

        if expected_count != 5:
            return

        self.minute_counts.pop(bar.time, None)

        if len(self.slow_closes) >= 20:
            previous_fast = sum(self.fast_closes) / Decimal(len(self.fast_closes))
            previous_slow = sum(self.slow_closes) / Decimal(len(self.slow_closes))
        else:
            previous_fast = None
            previous_slow = None

        self.fast_closes.append(bar.close)
        self.slow_closes.append(bar.close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / Decimal(len(self.fast_closes))
        current_slow = sum(self.slow_closes) / Decimal(len(self.slow_closes))

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end = bar.end_time
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter_call(bar.close)

    def _try_enter_call(self, spy_price):
        if self.no_entry_today:
            return

        if self.held_option is not None:
            return

        if self._entry_order_is_open():
            return

        chain = self.current_slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug(f"{self.time}: skipped entry; no option chain")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)

        contracts = list(chain.contracts.values())
        expiries = sorted({
            contract.expiry.date()
            for contract in contracts
            if contract.expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.debug(f"{self.time}: skipped entry; no valid expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * Decimal("1.01")

        candidates = [
            contract
            for contract in contracts
            if contract.expiry.date() == selected_expiry
            and contract.right == OptionRight.CALL
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"{self.time}: skipped entry; no qualifying call "
                f"for {selected_expiry}"
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                contract.strike,
                str(contract.symbol)
            )
        )[0]

        self.entry_ticket = self.market_order(
            selected.symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _process_held_option(self, slice: Slice):
        held_symbol = self.held_option
        position = self.portfolio[held_symbol]

        if position.quantity <= 0:
            return

        current_date = self.time.date()

        if current_date >= self.expiry_date:
            self.no_entry_today = True
            self._submit_exit("expiration protection")
            return

        prior_trading_day = self._previous_trading_day(self.expiry_date)

        if (
            current_date == prior_trading_day
            and self.time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            return

        contract = self._get_current_contract(slice, held_symbol)
        if contract is None:
            return

        bid = contract.bid_price
        ask = contract.ask_price

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / Decimal("2")

        if midpoint >= self.entry_price * Decimal("1.50"):
            self._submit_exit("50 percent profit target")

    def _get_current_contract(self, slice: Slice, symbol):
        chain = slice.option_chains.get(self.option_symbol)
        if chain is None:
            return None

        return chain.contracts.get(symbol)

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.portfolio[self.held_option].quantity
        if quantity <= 0:
            return

        if self._exit_order_is_open():
            return

        if self.exit_ticket is not None:
            self.exit_ticket.cancel("Replacing prior exit order")
            self.exit_ticket = None

        self.exit_ticket = self.market_order(
            self.held_option,
            -quantity,
            tag=reason
        )

        self.debug(f"{self.time}: submitted exit; reason={reason}")

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status == OrderStatus.FILLED:
            if (
                self.entry_ticket is not None
                and order_event.order_id == self.entry_ticket.order_id
                and order_event.fill_quantity > 0
            ):
                self.held_option = order_event.symbol
                self.entry_price = order_event.fill_price
                self.expiry_date = order_event.symbol.id.date.date()
                self.entry_ticket = None

                self.debug(
                    f"{self.time}: entered {order_event.symbol}; "
                    f"fill={order_event.fill_price}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.order_id == self.exit_ticket.order_id
            ):
                self.debug(
                    f"{self.time}: exited {order_event.symbol}; "
                    f"fill={order_event.fill_price}"
                )

                if self.portfolio[order_event.symbol].quantity == 0:
                    self.held_option = None
                    self.entry_price = None
                    self.expiry_date = None
                    self.exit_ticket = None

        elif (
            self.entry_ticket is not None
            and order_event.order_id == self.entry_ticket.order_id
            and order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            )
        ):
            self.debug(f"{self.time}: entry order did not fill")
            self.entry_ticket = None

    def on_assignment_order_event(self, assignment_event: OrderEvent):
        self.debug(
            f"{self.time}: unexpected option exercise or assignment"
        )
        self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        quantity = self.portfolio[self.spy].quantity

        if quantity != 0:
            self.debug(
                f"{self.time}: liquidating unexpected SPY equity position "
                f"of {quantity}"
            )
            self.market_order(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment cleanup"
            )
            self.no_entry_today = True

    def _entry_order_is_open(self):
