from AlgorithmImports import *
from datetime import datetime, timedelta


class ClockAlignedFiveMinuteConsolidator:
    """Consolidates complete regular-session minute bars on New York clock boundaries."""

    def __init__(self, symbol, handler):
        self.symbol = symbol
        self.handler = handler
        self.bucket_start = None
        self.bars = {}

    def update(self, bar: TradeBar):
        local_end = bar.EndTime
        minute_start = local_end - timedelta(minutes=1)

        if not (9 <= minute_start.hour <= 15):
            return

        minute_of_day = minute_start.hour * 60 + minute_start.minute
        if minute_of_day < 570 or minute_of_day >= 960:
            return

        bucket_minute = (minute_start.minute // 5) * 5
        bucket_start = minute_start.replace(
            minute=bucket_minute, second=0, microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._emit_previous()
            self.bucket_start = bucket_start
            self.bars = {}

        self.bars[minute_start] = bar

    def _emit_previous(self):
        if self.bucket_start is None:
            return

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self.bars for t in expected):
            self.bars = {}
            return

        minute_bars = [self.bars[t] for t in expected]

        consolidated = TradeBar(
            self.bucket_start,
            self.symbol,
            minute_bars[0].Open,
            max(x.High for x in minute_bars),
            min(x.Low for x in minute_bars),
            minute_bars[-1].Close,
            sum(x.Volume for x in minute_bars),
            timedelta(minutes=5)
        )

        self.handler(consolidated)
        self.bars = {}


